messages.content:
Here's a complete, dependency-free build: **Archivist** — a chat client whose sessions are *files*. One JSON document per conversation on disk, an archive rail you can live inside, and a raw-record drawer so you always see exactly what just got written.

## `server.js` — zero-dependency Node, JSON-per-session storage

```javascript
import http from 'node:http';
import fsp from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = path.join(ROOT, 'public');
const DATA_DIR = process.env.DATA_DIR ? path.resolve(process.env.DATA_DIR) : path.join(ROOT, 'data', 'sessions');
const PORT = Number(process.env.PORT || 4173);
const HOST = process.env.HOST || '127.0.0.1';
const MAX_BODY = 2 * 1024 * 1024;
const ID_RE = /^[A-Za-z0-9_-]{4,64}$/;

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
};

/* ────────────────────────── storage primitives ────────────────────────── */

const nowISO = () => new Date().toISOString();
const makeId = () => Date.now().toString(36) + '-' + crypto.randomBytes(4).toString('hex');
const validDate = (v) => { const d = new Date(v); return Number.isNaN(+d) ? null : d.toISOString(); };
const fileFor = (id) => {
  if (!ID_RE.test(id)) throw Object.assign(new Error('bad session id'), { status: 400 });
  return path.join(DATA_DIR, `${id}.json`);
};
const cleanTitle = (v, fallback = 'Untitled session') => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  return (s || fallback).slice(0, 120);
};
const normalizeMessage = (m) => ({
  id: typeof m?.id === 'string' && m.id ? m.id.slice(0, 64) : makeId(),
  role: ['user', 'assistant', 'system'].includes(m?.role) ? m.role : 'user',
  content: String(m?.content ?? '').slice(0, 20000),
  ts: Number.isFinite(+m?.ts) ? +m.ts : Date.now(),
});

function normalizeSession(raw, id) {
  const createdAt = validDate(raw?.createdAt) || nowISO();
  return {
    id,
    title: cleanTitle(raw?.title),
    createdAt,
    updatedAt: validDate(raw?.updatedAt) || createdAt,
    pinned: Boolean(raw?.pinned),
    messages: Array.isArray(raw?.messages) ? raw.messages.slice(0, 2000).map(normalizeMessage) : [],
  };
}

function summarize(s, raw) {
  const firstUser = s.messages.find((m) => m.role === 'user') || s.messages[0];
  return {
    id: s.id,
    title: s.title,
    createdAt: s.createdAt,
    updatedAt: s.updatedAt,
    pinned: s.pinned,
    bytes: Buffer.byteLength(raw ?? '', 'utf8'),
    messageCount: s.messages.length,
    preview: (firstUser?.content || 'No messages yet').replace(/\s+/g, ' ').slice(0, 110),
    excerpt: s.messages.map((m) => m.content).join('\n').slice(0, 3000).toLowerCase(),
  };
}

async function writeSession(session) {
  const file = fileFor(session.id);
  const tmp = `${file}.${process.pid}.tmp`;
  const json = JSON.stringify(session, null, 2) + '\n';
  await fsp.mkdir(DATA_DIR, { recursive: true });
  await fsp.writeFile(tmp, json, 'utf8');       // atomic: temp file, then rename
  await fsp.rename(tmp, file);
  return json;
}

async function readSession(id) {
  const raw = await fsp.readFile(fileFor(id), 'utf8');
  return normalizeSession(JSON.parse(raw), id);
}

async function listSessions() {
  const names = await fsp.readdir(DATA_DIR).catch(() => []);
  const out = [];
  for (const name of names) {
    if (!name.endsWith('.json')) continue;
    const id = name.slice(0, -5);
    if (!ID_RE.test(id)) continue;
    try {
      const raw = await fsp.readFile(path.join(DATA_DIR, name), 'utf8');
      out.push(summarize(normalizeSession(JSON.parse(raw), id), raw));
    } catch (err) {
      console.warn(`skipping unreadable session ${name}:`, err.message);
    }
  }
  out.sort((a, b) => (b.pinned - a.pinned) || (b.updatedAt > a.updatedAt ? 1 : -1));
  return out;
}

/* ────────────────────────── tiny http plumbing ────────────────────────── */

const json = (res, status, data) => {
  const body = JSON.stringify(data);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
};

function readBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > MAX_BODY) return reject(Object.assign(new Error('payload too large'), { status: 413 }));
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function parseJSON(req) {
  const raw = await readBody(req);
  if (!raw) return {};
  try { return JSON.parse(raw); }
  catch { throw Object.assign(new Error('invalid JSON body'), { status: 400 }); }
}

async function api(req, res, pathname) {
  if (pathname === '/api/health') {
    return json(res, 200, { ok: true, dataDir: DATA_DIR, time: nowISO() });
  }

  const seg = pathname.split('/').filter(Boolean);   // ['api','sessions',id?]
  if (seg[1] !== 'sessions') return json(res, 404, { error: 'not found' });
  const id = seg[2] ? decodeURIComponent(seg[2]) : null;

  // GET /api/sessions  ·  POST /api/sessions
  if (!id) {
    if (req.method === 'GET') {
      const sessions = await listSessions();
      const bytes = sessions.reduce((n, s) => n + s.bytes, 0);
      return json(res, 200, { sessions, count: sessions.length, bytes, dataDir: DATA_DIR });
    }
    if (req.method === 'POST') {
      const body = await parseJSON(req);
      const newId = body.id && ID_RE.test(body.id) ? body.id : makeId();
      const session = normalizeSession({ ...body, createdAt: body.createdAt ?? nowISO() }, newId);
      const raw = await writeSession(session);
      return json(res, 201, { session, summary: summarize(session, raw) });
    }
    return json(res, 405, { error: 'method not allowed' });
  }

  // /api/sessions/:id
  if (req.method === 'GET') {
    const session = await readSession(id).catch((e) => {
      if (e.code === 'ENOENT') throw Object.assign(new Error('session not found'), { status: 404 });
      throw e;
    });
    return json(res, 200, { session, summary: summarize(session, JSON.stringify(session)) });
  }

  if (req.method === 'PUT' || req.method === 'PATCH') {
    const body = await parseJSON(req);
    const existing = await readSession(id).catch((e) =>
      e.code === 'ENOENT' ? normalizeSession({}, id) : Promise.reject(e));

    const next = { ...existing };
    if ('title' in body) next.title = cleanTitle(body.title, existing.title);
    if ('pinned' in body) next.pinned = Boolean(body.pinned);
    if (Array.isArray(body.messages)) next.messages = body.messages.slice(0, 2000).map(normalizeMessage);
    next.createdAt = existing.createdAt;
    next.updatedAt = nowISO();                       // the server owns the clock

    const raw = await writeSession(next);
    return json(res, 200, { session: next, summary: summarize(next, raw) });
  }

  if (req.method === 'DELETE') {
    await fsp.rm(fileFor(id), { force: true });
    return json(res, 204, null);
  }

  return json(res, 405, { error: 'method not allowed' });
}

async function serveStatic(req, res, pathname) {
  if (req.method !== 'GET' && req.method !== 'HEAD') return json(res, 405, { error: 'method not allowed' });
  const rel = pathname === '/' ? '/index.html' : path.posix.normalize(pathname);
  const file = path.join(PUBLIC_DIR, rel);
  if (!file.startsWith(PUBLIC_DIR)) return json(res, 403, { error: 'forbidden' });

  try {
    const data = await fsp.readFile(file);
    res.writeHead(200, {
      'Content-Type': MIME[path.extname(file)] || 'application/octet-stream',
      'Cache-Control': 'no-store',
    });
    res.end(req.method === 'HEAD' ? undefined : data);
  } catch {
    if (path.extname(file)) return json(res, 404, { error: 'not found' });
    const html = await fsp.readFile(path.join(PUBLIC_DIR, 'index.html'));
    res.writeHead(200, { 'Content-Type': MIME['.html'], 'Cache-Control': 'no-store' });
    res.end(html);
  }
}

/* ────────────────────────── boot ────────────────────────── */

const SEED = {
  title: 'Welcome to the archive',
  messages: [
    { role: 'user', content: 'Where does any of this actually live?' },
    { role: 'assistant', content: 'On disk. Every session is one JSON file inside ./data/sessions — id, title, timestamps, and the full message array. Nothing is held only in memory; refresh the page and the transcript walks back in.' },
    { role: 'user', content: 'And if I delete something?' },
    { role: 'assistant', content: 'The file is removed. The toast that follows gives you a few seconds of undo, which simply writes the record back under the same name. After that it is gone for real.' },
  ],
};

async function seedIfEmpty() {
  await fsp.mkdir(DATA_DIR, { recursive: true });
  const names = await fsp.readdir(DATA_DIR);
  if (names.some((n) => n.endsWith('.json'))) return;
  const base = Date.now();
  await writeSession(normalizeSession({
    ...SEED,
    createdAt: new Date(base - 6e4).toISOString(),
    updatedAt: new Date(base - 6e4).toISOString(),
    messages: SEED.messages.map((m, i) => ({ ...m, ts: base - (SEED.messages.length - i) * 40000 })),
  }, makeId()));
  console.log('· seeded a welcome session');
}

const server = http.createServer(async (req, res) => {
  const { pathname } = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  try {
    if (pathname.startsWith('/api/')) return await api(req, res, pathname);
    return await serveStatic(req, res, pathname);
  } catch (err) {
    const status = err.status || 500;
    if (status >= 500) console.error(err);
    json(res, status, { error: err.message || 'server error' });
  }
});

await seedIfEmpty();
server.listen(PORT, HOST, () => {
  console.log(`\n  Archivist → http://${HOST}:${PORT}`);
  console.log(`  sessions  → ${DATA_DIR}\n`);
});
```

## `public/index.html`

```html
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Archivist — chat that writes itself to disk</title>
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wdth,wght@12..96,75..100,500;12..96,75..100,700;12..96,75..100,800&family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap" rel="stylesheet" />
<link rel="stylesheet" href="/styles.css" />
</head>
<body>
<div class="app" id="app">

  <!-- ═══════════ archive rail ═══════════ -->
  <aside class="rail" id="rail" aria-label="Session archive">
    <div class="rail__brand">
      <div class="mark" aria-hidden="true"><span></span><span></span><span></span></div>
      <div>
        <h1 class="brand">Archivist</h1>
        <p class="brand__sub">chat <i>→</i> disk</p>
      </div>
      <i class="led" id="led" title="disk activity"></i>
    </div>

    <button class="newchat" id="newChat">
      <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2.5v11M2.5 8h11" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
      New chat
      <kbd>⌥⌘N</kbd>
    </button>

    <div class="search">
      <svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="7" cy="7" r="4.2" stroke="currentColor" stroke-width="1.6" fill="none"/><path d="m10.4 10.4 3 3" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
      <input id="search" type="search" placeholder="Filter sessions…" aria-label="Filter sessions" />
      <kbd>⌘K</kbd>
    </div>

    <div class="rail__count"><span id="countLabel">0 sessions</span></div>
    <nav class="sessions" id="sessionList" role="list"></nav>

    <footer class="rail__foot">
      <div class="disk">
        <span class="disk__label">on disk</span>
        <strong id="diskBytes">0 B</strong>
        <code id="diskDir">./data/sessions</code>
      </div>
      <ul class="writelog" id="writeLog" aria-hidden="true"></ul>
    </footer>
  </aside>

  <!-- ═══════════ stage ═══════════ -->
  <main class="stage">
    <header class="head">
      <button class="iconbtn only-narrow" id="btnRail" aria-label="Toggle archive">☰</button>
      <div class="head__main">
        <p class="eyebrow"><span id="headSid">—</span> · <span id="headState">loading</span></p>
        <h2 class="head__title" id="headTitle" contenteditable="true" spellcheck="false" data-ph="Untitled session"></h2>
      </div>
      <div class="head__stats" id="headStats">
        <div class="stat"><b id="mcount">0</b><span>messages</span></div>
        <div class="stat"><b id="fsize">0</b><span>KB on disk</span></div>
      </div>
      <div class="head__actions">
        <button class="iconbtn" id="btnExport" title="Download this session as JSON (⌘E)">
          <svg viewBox="0 0 16 16"><path d="M8 2v8m0 0 3-3M8 10 5 7M2.5 12.5h11" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round"/></svg>
        </button>
        <button class="iconbtn" id="btnRaw" title="Toggle raw record (⌘J)">
          <svg viewBox="0 0 16 16"><path d="M6 3 2.5 8 6 13M10 3l3.5 5L10 13" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </button>
        <button class="delbtn" id="btnDelete" title="Delete this session">
          <span class="delbtn__idle">Delete</span>
          <span class="delbtn__ask">Sure? </span>
          <span class="delbtn__btns"><b data-yes>yes</b><b data-no>no</b></span>
        </button>
      </div>
    </header>

    <div class="stamp">
      <span>created <em id="headCreated">—</em></span>
      <span class="sep"></span>
      <span>updated <em id="headUpdated">—</em></span>
      <span class="sep"></span>
      <code id="headPath">—</code>
    </div>

    <div class="threadwrap" id="threadwrap">
      <div class="thread" id="thread"></div>
    </div>

    <form class="composer" id="composer" autocomplete="off">
      <div class="composer__row">
        <textarea id="input" rows="1" placeholder="Say something — it hits the disk before it hits the screen…" aria-label="Message"></textarea>
        <button class="send" type="submit">
          <span>Send</span>
          <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2 8h11m0 0-4-4m4 4-4 4" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </button>
      </div>
      <div class="composer__foot">
        <span class="pill" id="savePill" data-state="idle"><i></i><span id="saveText">idle</span></span>
        <span class="hint"><kbd>Enter</kbd> send · <kbd>⇧Enter</kbd> newline</span>
        <span class="counter" id="counter">0 chars</span>
      </div>
    </form>
  </main>

  <!-- ═══════════ raw record ═══════════ -->
  <aside class="inspector" id="inspector" aria-label="Raw JSON record">
    <header class="insp__head">
      <h3>Raw record</h3>
      <button class="iconbtn" id="btnRawClose" aria-label="Close raw record">✕</button>
    </header>
    <p class="insp__path"><code id="rawPath">—</code> · <span id="rawBytes">0 B</span></p>
    <pre class="insp__code" id="rawCode"></pre>
    <footer class="insp__foot">What you see here is what is on disk. <kbd>⌘J</kbd> to hide.</footer>
  </aside>
</div>

<div class="toasts" id="toasts" role="status" aria-live="polite"></div>
<script src="/app.js"></script>
</body>
</html>
```

## `public/styles.css`

```css
/* ── tokens ───────────────────────────────────────────────────── */
:root{
  --ink-900:#0B0E13; --ink-800:#11161D; --ink-700:#1A212A; --ink-600:#28313D;
  --paper:#F3F1EA; --paper-2:#FBFAF5; --card:#FFFFFF;
  --text:#15191F; --muted:#6A7382; --line:#DFDCD1;
  --teal:#0E6B58; --teal-soft:#DDEDE7;
  --lime:#D7F05C; --coral:#CC4326; --sky:#9CC4FF;
  --shadow:0 1px 0 rgba(20,25,32,.04), 0 10px 30px -18px rgba(20,25,32,.45);
  --mono:"IBM Plex Mono",ui-monospace,Menlo,monospace;
  --sans:"IBM Plex Sans",system-ui,-apple-system,sans-serif;
  --disp:"Bricolage Grotesque","IBM Plex Sans",system-ui,sans-serif;
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0; font-family:var(--sans); color:var(--text); background:var(--ink-900);
  font-size:15px; -webkit-font-smoothing:antialiased; overflow:hidden;
}
kbd{
  font-family:var(--mono); font-size:9.5px; letter-spacing:.06em; padding:2px 4px;
  border-radius:3px; border:1px solid currentColor; opacity:.55; white-space:nowrap;
}

/* ── shell ────────────────────────────────────────────────────── */
.app{
  display:grid; height:100vh;
  grid-template-columns:302px minmax(0,1fr) 0px;
  transition:grid-template-columns .32s cubic-bezier(.2,.8,.2,1);
}
.app[data-raw="open"]{grid-template-columns:302px minmax(0,1fr) 348px}

/* ── rail ─────────────────────────────────────────────────────── */
.rail{
  position:relative; display:flex; flex-direction:column; min-height:0;
  background:linear-gradient(176deg,#151B23,#0A0D12 62%);
  color:#E6EAF1; border-right:1px solid #000; overflow:hidden;
}
.rail::before{ /* hairline column grid */
  content:""; position:absolute; inset:0; pointer-events:none; opacity:.5;
  background:repeating-linear-gradient(90deg,rgba(255,255,255,.045) 0 1px,transparent 1px 34px);
  mask-image:linear-gradient(180deg,#000,transparent 88%);
}
.rail::after{ /* slow sheen */
  content:""; position:absolute; left:-40%; top:-20%; width:80%; height:70%; pointer-events:none;
  background:radial-gradient(60% 60% at 50% 40%,rgba(215,240,92,.11),transparent 70%);
  animation:drift 26s ease-in-out infinite alternate;
}
@keyframes drift{to{transform:translate3d(55%,45%,0) scale(1.15)}}

.rail__brand{display:flex; align-items:center; gap:11px; padding:18px 18px 14px}
.mark{display:grid; gap:2px}
.mark span{display:block; width:15px; height:3px; background:var(--lime); border-radius:1px}
.mark span:nth-child(2){width:10px; opacity:.6} .mark span:nth-child(3){width:6px; opacity:.35}
.brand{font-family:var(--disp); font-weight:800; font-size:19px; letter-spacing:-.02em; margin:0; line-height:1}
.brand__sub{margin:3px 0 0; font-family:var(--mono); font-size:9.5px; letter-spacing:.22em; text-transform:uppercase; color:#7C879A}
.brand__sub i{color:var(--lime); font-style:normal}
.led{width:7px; height:7px; border-radius:50%; background:#39414F; margin-left:auto; transition:background .1s, box-shadow .25s}
.led.on{background:var(--lime); box-shadow:0 0 0 4px rgba(215,240,92,.16)}

.newchat{
  display:flex; align-items:center; gap:9px; margin:0 14px 12px; padding:11px 12px;
  background:var(--lime); color:#0C1002; border:0; border-radius:8px; cursor:pointer;
  font-family:var(--sans); font-weight:600; font-size:13.5px; letter-spacing:-.01em;
  box-shadow:0 6px 18px -10px rgba(215,240,92,.9); transition:transform .16s, box-shadow .2s, filter .2s;
}
.newchat svg{width:13px;height:13px}
.newchat kbd{margin-left:auto; border-color:rgba(0,0,0,.3); opacity:.5}
.newchat:hover{transform:translateY(-1.5px); box-shadow:0 12px 24px -12px rgba(215,240,92,1); filter:brightness(1.04)}
.newchat:active{transform:translateY(0)}

.search{display:flex; align-items:center; gap:8px; margin:0 14px 10px; padding:0 9px; background:rgba(255,255,255,.055); border:1px solid rgba(255,255,255,.08); border-radius:8px; transition:border-color .2s,background .2s}
.search:focus-within{border-color:rgba(215,240,92,.5); background:rgba(215,240,92,.07)}
.search svg{width:14px;height:14px;color:#8B96A8; flex:none}
.search input{flex:1; min-width:0; background:none; border:0; outline:0; color:#EDF0F5; font:400 13px/2.3 var(--sans)}
.search input::placeholder{color:#6C footer}
.search input::placeholder{color:#6A footer}
.search ::placeholder{color:#69 footer}
.search input::-webkit-search-cancel-button{filter:invert(.7)}
.search kbd{color:#8B96A8}

.rail__count{padding:2px 20px 8px; font-family:var(--mono); font-size:9.5px; letter-spacing:.2em; text-transform:uppercase; color:#6E footer}
.rail__count{padding:2px 20px 8px; font-family:var(--mono); font-size:9.5px; letter-spacing:.2em; text-transform:uppercase; color:#6C footer}
.rail__count span{color:#6C footer}

.sessions{flex:1; min-height:0; overflow-y:auto; padding:0 10px 14px; scrollbar-width:thin; scrollbar-color:#2C3441 transparent}
.sessions::-webkit-scrollbar{width:9px} .sessions::-webkit-scrollbar-thumb{background:#2C3441; border-radius:9px; border:3px solid transparent; background-clip:content-box}

.ses{position:relative; display:block; width:100%; text-align:left; padding:11px 12px 10px 14px; border-radius:9px; cursor:pointer; color:#C9D1DE; border:1px solid transparent; transition:background .18s, border-color .18s, transform .18s; animation:rise .3s backwards}
@keyframes rise{from{opacity:0; transform:translateY(6px)}}
.ses:hover{background:rgba(255,255,255,.05); transform:translateX(2px)}
.ses:focus-visible{outline:2px solid var(--lime); outline-offset:1px}
.ses__bar{position:absolute; left:3px; top:50%; width:2px; height:14%; border-radius:2px; background:var(--lime); transform:translateY(-50%); opacity:0; transition:height .25s, opacity .25s}
.ses.is-active{background:rgba(215,240,92,.09); border-color:rgba(215,240,92,.18); color:#FFF}
.ses.is-active .ses__bar{opacity:1; height:56%}
.ses__top{display:flex; align-items:baseline; gap:8px}
.ses__title{flex:1; min-width:0; font-size:13.3px; font-weight:500; letter-spacing:-.01em; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}
.ses__pin{color:var(--lime); font-size:10px}
.ses time{font-family:var(--mono); font-size:9.5px; color:#78 footer; flex:none; letter-spacing:.04em}
.ses time{font-family:var(--mono); font-size:9.5px; color:#77 footer}
