/* ── stage ────────────────────────────────────────────────────── */
.stage{
  position:relative; display:flex; flex-direction:column; min-width:0; min-height:0;
  background:var(--paper);
}
.stage::before{ /* graph paper + drifting light */
  content:""; position:absolute; inset:0; pointer-events:none;
  background:
    radial-gradient(48% 38% at 78% 6%, rgba(255,255,255,.9), transparent 70%),
    radial-gradient(40% 30% at 4% 94%, rgba(14,107,88,.07), transparent 70%),
    repeating-linear-gradient(0deg, rgba(21,25,31,.028) 0 1px, transparent 1px 28px),
    repeating-linear-gradient(90deg, rgba(21,25,31,.022) 0 1px, transparent 1px 28px);
  animation:wash 30s ease-in-out infinite alternate;
}
@keyframes wash{to{background-position:0 0, 0 0, 0 14px, 14px 0}}

.head{position:relative; z-index:2; display:grid; grid-template-columns:minmax(0,1fr) auto auto; align-items:start; gap:20px; padding:20px 30px 12px; border-bottom:1px solid var(--line); background:linear-gradient(180deg,rgba(251,250,245,.92),rgba(251,250,245,.62)); backdrop-filter:blur(6px)}
.head__main{min-width:0}
.eyebrow{margin:0 0 5px; font-family:var(--mono); font-size:9.5px; letter-spacing:.2em; text-transform:uppercase; color:var(--muted)}
.eyebrow span:first-child{color:var(--teal)}
.head__title{
  margin:0; font-family:var(--disp); font-weight:800; font-size:clamp(23px,2.6vw,34px);
  line-height:1.06; letter-spacing:-.03em; max-width:22ch; outline:0; border-radius:5px;
  padding:1px 5px; margin-left:-5px; transition:background .2s, box-shadow .2s;
}
.head__title:hover{background:rgba(14,107,88,.05)}
.head__title:focus{background:#fff; box-shadow:0 0 0 2px var(--teal), var(--shadow)}
.head__title:empty::before{content:attr(data-ph); color:#A9B0BA}

.head__stats{display:flex; gap:22px; padding-top:4px}
.stat{text-align:right}
.stat b{display:block; font-family:var(--disp); font-weight:800; font-size:27px; line-height:1; letter-spacing:-.03em}
.stat span{font-family:var(--mono); font-size:8.5px; letter-spacing:.18em; text-transform:uppercase; color:var(--muted)}
.head__actions{display:flex; align-items:center; gap:8px}

.iconbtn{width:32px;height:32px; display:grid; place-items:center; padding:0; border:1px solid var(--line); border-radius:8px; background:var(--card); color:#4B5563; cursor:pointer; transition:.16s}
.iconbtn svg{width:15px;height:15px}
.iconbtn:hover{color:var(--text); border-color:#B9C0C8; transform:translateY(-1px); box-shadow:var(--shadow)}
.iconbtn.is-on{background:var(--ink-800); color:var(--lime); border-color:var(--ink-800)}

.delbtn{position:relative; border:1px solid var(--line); background:var(--card); color:var(--coral); border-radius:8px; height:32px; padding:0 12px; font:500 12px var(--sans); cursor:pointer; transition:.16s}
.delbtn:hover{border-color:var(--coral); background:rgba(204,67,38,.06)}
.delbtn__ask,.delbtn__btns{display:none}
.delbtn.confirming{background:var(--coral); color:#fff; border-color:var(--coral)}
.delbtn.confirming .delbtn__idle{display:none}
.delbtn.confirming .delbtn__ask{display:inline}
.delbtn.confirming .delbtn__btns{display:inline-flex; gap:5px; margin-left:3px}
.delbtn.confirming .delbtn__btns b{padding:1px 6px; border-radius:4px; background:rgba(255,255,255,.22)}
.delbtn.confirming .delbtn__btns b:hover{background:#fff; color:var(--coral)}

.stamp{position:relative; z-index:2; display:flex; flex-wrap:wrap; align-items:center; gap:10px; padding:7px 30px; font-family:var(--mono); font-size:10px; letter-spacing:.05em; color:var(--muted); border-bottom:1px solid var(--line); background:rgba(243,241,234,.7)}
.stamp em{font-style:normal; color:var(--text)}
.stamp .sep{width:3px;height:3px;border-radius:50%;background:#C6C2B6}
