/* ── thread ───────────────────────────────────────────────────── */
.threadwrap{position:relative; z-index:1; flex:1; min-height:0; overflow-y:auto; padding:26px 30px 8px; scrollbar-width:thin}
.thread{display:flex; flex-direction:column; gap:18px; max-width:760px; margin:0 auto}

.msg{display:flex; gap:12px; animation:pop .34s cubic-bezier(.2,.9,.25,1) backwards}
@keyframes pop{from{opacity:0; transform:translateY(10px) scale(.99)}}
.msg__mark{flex:none; width:28px; height:28px; display:grid; place-items:center; border-radius:7px; font-family:var(--mono); font-size:11px; font-weight:500; letter-spacing:.02em}
.msg__body{min-width:0; flex:1}
