.msg__bubble{position:relative; padding:12px 15px; border-radius:3px 12px 12px 12px; font-size:14.6px; line-height:1.62; white-space:pre-wrap; word-break:break-word; box-shadow:var(--shadow)}
.msg__bubble p{margin:0 0 .7em} .msg__bubble p:last-child{margin:0}
.msg--assistant .msg__mark{background:var(--teal); color:#EAF6F1}
.msg--assistant .msg__bubble{background:var(--card); border:1px solid var(--line); border-left:3px solid var(--teal)}
.msg--user{flex-direction:row-reverse}
.msg--user .msg__mark{background:var(--ink-800); color:var(--lime)}
.msg--user .msg__meta{flex-direction:row-reverse}
.msg--user .msg__bubble{background:var(--ink-800); color:#F1F3F7; border-radius:12px 3px 12px 12px; border-left:0}
.msg__copy{position:absolute; top:6px; right:8px; opacity:0; border:0; background:rgba(0,0,0,.06); color:inherit; border-radius:5px; padding:2px 7px; font:500 9.5px var(--mono); letter-spacing:.1em; text-transform:uppercase; cursor:pointer; transition:.16s}
.msg:hover .msg__copy{opacity:.75}
.msg__copy:hover{opacity:1 !important}
.typing i{display:inline-block; width:5px; height:5px; margin-right:3px; border-radius:50%; background:var(--muted); animation:blink 1.1s infinite}
.typing i:nth-child(2){animation-delay:.18s} .typing i:nth-child(3){animation-delay:.36s}
@keyframes blink{0%,60%,100%{opacity:.25; transform:translateY(0)} 30%{opacity:1; transform:translateY(-3px)}}

.empty{max-width:520px; margin:6vh auto 0; text-align:left}
.empty .stack{display:grid; gap:4px; margin-bottom:20px}
.empty .stack i{display:block; height:9px; border:1px solid var(--line); border-radius:2px; background:#fff}
