.empty h3{font-family:var(--disp); font-weight:800; font-size:clamp(28px,4.4vw,46px); letter-spacing:-.035em; line-height:.98; margin:0 0 12px}
.empty p{margin:0 0 18px; color:var(--muted); font-size:14.5px; line-height:1.6; max-width:42ch}
.empty .keys{display:flex; flex-wrap:wrap; gap:8px; font-family:var(--mono); font-size:10px; letter-spacing:.06em; color:var(--muted)}
.empty .keys span{border:1px solid var(--line); background:#fff; border-radius:20px; padding:5px 11px}

/* ── composer ─────────────────────────────────────────────────── */
.composer{position:relative; z-index:3; padding:12px 30px 16px; background:linear-gradient(180deg,rgba(243,241,234,0),rgba(243,241,234,.9) 34%); border-top:1px solid var(--line)}
.composer__row{display:flex; gap:10px; align-items:flex-end; max-width:760px; margin:0 auto; background:var(--card); border:1px solid var(--line); border-radius:12px; padding:9px 9px 9px 15px; box-shadow:var(--shadow); transition:border-color .2s, box-shadow .2s}
.composer__row:focus-within{border-color:var(--teal); box-shadow:0 0 0 3px rgba(14,107,88,.12), var(--shadow)}
.composer textarea{flex:1; border:0; outline:0; resize:none; background:none; font:400 15px/1.55 var(--sans); color:var(--text); max-height:180px; padding:5px 0}
.composer textarea::placeholder{color:#A7AEB8}
.send{display:flex; align-items:center; gap:7px; border:0; border-radius:8px; padding:9px 14px; background:var(--ink-800); color:#fff; font:600 13px var(--sans); cursor:pointer; transition:.16s}
.send svg{width:14px;height:14px}
.send:hover{background:var(--teal)} .send:hover svg{transform:translateX(2px)}
.send svg{transition:transform .16s}
.send:disabled{opacity:.4; cursor:not-allowed}
.composer__foot{display:flex; align-items:center; gap:12px; max-width:760px; margin:8px auto 0; font-family:var(--mono); font-size:9.5px; letter-spacing:.1em; text-transform:uppercase; color:var(--muted)}
.composer__foot .hint{margin-left:auto} .counter{min-width:62px; text-align:right}
.pill{display:inline-flex; align-items:center; gap:6px; padding:3px 9px 3px 7px; border-radius:20px; border:1px solid var(--line); background:#fff; letter-spacing:.12em}
.pill i{width:6px;height:6px;border-radius:50%; background:#C0BDB2; transition:.2s}
.pill[data-state="saving"] i{background:var(--lime); animation:throb .7s infinite}
.pill[data-state="saving"]{border-color:rgba(215,240,92,.9); background:rgba(215,240,92,.16)}
.pill[data-state="saved"] i{background:var(--teal)}
.pill[data-state="error"] i{background:var(--coral)} .pill[data-state="error"]{color:var(--coral); border-color:var(--coral)}
@keyframes throb{50%{transform:scale(1.5)}}

/* ── inspector ────────────────────────────────────────────────── */
.inspector{position:relative; display:flex; flex-direction:column; min-width:0; overflow:hidden; background:linear-gradient(180deg,#11161D,#0A0D12); color:#D6DCE6; border-left:1px solid #000}
.insp__head{display:flex; align-items:center; justify-content:space-between; padding:18px 16px 10px}
.insp__head h3{margin:0; font-family:var(--disp); font-weight:700; font-size:13px; letter-spacing:.02em}
.insp__path{margin:0 16px 10px; font-family:var(--mono); font-size:9.5px; letter-spacing:.08em; color:#78 footer}
.insp__path{color:#77808F}
.insp__path code{color:var(--lime)}
.insp__code{flex:1; min-height:0; overflow:auto; margin:0; padding:14px 16px 20px; font:400 11px/1.72 var(--mono); white-space:pre-wrap; word-break:break-word; color:#B9C3D1; border-top:1px solid rgba(255,255,255,.07); scrollbar-width:thin}
.j-key{color:var(--lime)} .j-str{color:#8FD3C0} .j-num{color:var(--sky)} .j-bool{color:#E8A87C} .j-null{color:#8B94A3}
.insp__foot{padding:10px 16px 14px; border-top:1px solid rgba(255,255,255,.07); font-size:10.5px; color:#77808F}

/* ── toasts ───────────────────────────────────────────────────── */
.toasts{position:fixed; left:22px; bottom:22px; z-index:50; display:grid; gap:8px}
.toast{display:flex; align-items:center; gap:11px; padding:11px 13px; border-radius:9px; background:var(--ink-800); color:#EEF1F6; font-size:13px; box-shadow:0 18px 40px -20px rgba(0,0,0,.7); animation:slidein .28s cubic-bezier(.2,.9,.25,1); border-left:3px solid var(--lime); max-width:340px}
.toast.bad{border-left-color:var(--coral)} .toast.warn{border-left-color:#E8A87C}
.toast button{border:1px solid rgba(255,255,255,.24); background:none; color:#fff; border-radius:6px; padding:3px 9px; font:600 11px var(--sans); cursor:pointer}
.toast button:hover{background:var(--lime); color:#0C1002; border-color:var(--lime)}
@keyframes slidein{from{opacity:0; transform:translateY(12px) scale(.97)}}
.toast.out{opacity:0; transform:translateY(8px); transition:.22s}

/* ── responsive ───────────────────────────────────────────────── */
.only-narrow{display:none}
@media (max-width:1080px){ .app[data-raw="open"]{grid-template-columns:302px minmax(0,1fr) 0} .inspector{position:absolute; right:0; top:0; bottom:0; width:min(380px,86vw); z-index:40; box-shadow:-24px 0 60px -30px rgba(0,0,0,.6)} .app:not([data-raw="open"]) .inspector{transform:translateX(100%)} }
@media (max-width:820px){
  .app,.app[data-raw="open"]{grid-template-columns:1fr}
  .rail{position:absolute; left:0; top:0; bottom:0; width:min(310px,86vw); z-index:45; transition:transform .3s cubic-bezier(.2,.8,.2,1); box-shadow:24px 0 60px -30px rgba(0,0,0,.6)}
  .app:not([data-rail="open"]) .rail{transform:translateX(-101%)}
  .only-narrow{display:grid}
  .head{grid-template-columns:minmax(0,1fr) auto; padding:16px 18px 11px; gap:12px}
  .head__stats{grid-column:2; order:3; flex-direction:column; gap:10px; display:none}
  .threadwrap,.composer{padding-left:18px; padding-right:18px}
  .stat b{font-size:20px}
}
@media (prefers-reduced-motion:reduce){ *{animation:none !important; transition:none !important} }
```

