```javascript
/* ───────────────────────── helpers ───────────────────────── */
const $ = (s, r = document) => r.querySelector(s);
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const uid = () => Math.random().toString(36).slice(2, 10);
const KB = (n) => (n / 1024).toFixed(n < 10240 ? 2 : 1);
const bytesLabel = (n) => (n < 1024 ? `${n} B` : n < 1048576 ? `${KB(n)} KB` : `${(n / 1048576).toFixed(2)} MB`);
const clock = (ts) => new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
const full = (ts) => new Date(ts).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
const isMac = /Mac|iP(hone|ad|od)/.test(navigator.platform);
const cmd = isMac ? '⌘' : 'Ctrl';

function rel(iso) {
  const d = (Date.now() - new Date(iso)) / 1000;
  if (d < 45) return 'now';
  if (d < 3600) return `${Math.round(d / 60)}m`;
  if (d < 86400) return `${Math.round(d / 3600)}h`;
  if (d < 86400 * 7) return `${Math.round(d / 86400)}d`;
  return new Date(iso).toLocaleDateString([], { month: 'short', day: 'numeric' });
}
const ICON = {
  trash: '<svg viewBox="0 0 16 16"><path d="M3.5 4.5h9M6.5 4V2.8h3V4M5 4.5l.6 8.2h4.8l.6-8.2" stroke="currentColor" fill="none" stroke-width="1.4" stroke-linecap="round"/></svg>',
  pin: '<svg viewBox="0 0 16 16"><path d="M8 9.6V14M5 2.5h6l-.8 3.2 1.8 2.1v.9H4v-.9l1.8-2.1z" stroke="currentColor" fill="none" stroke-width="1.3" stroke-linejoin="round"/></svg>',
  copy: '<svg viewBox="0 0 16 16"><rect x="5.4" y="5.4" width="7.6" height="7.6" rx="1.4" stroke="currentColor" fill="none" stroke-width="1.3"/><path d="M10.6 3.2H4.4A1.4 1.4 0 0 0 3 4.6v6" stroke="currentColor" fill="none" stroke-width="1.3"/></svg>',
};

/* ───────────────────────── state ───────────────────────── */
const state = { sessions: [], current: null, query: '', rawOpen: false, saveTimer: null, confirmTimer: null };
const els = {
  app: $('#app'), list: $('#sessionList'), search: $('#search'), newChat: $('#newChat'),
  thread: $('#thread'), threadwrap: $('#threadwrap'), input: $('#input'), composer: $('#composer'),
  title: $('#headTitle'), sid: $('#headSid'), headState: $('#headState'), created: $('#headCreated'),
  updated: $('#headUpdated'), path: $('#headPath'), mcount: $('#mcount'), fsize: $('#fsize'),
  countLabel: $('#countLabel'), diskBytes: $('#diskBytes'), diskDir: $('#diskDir'), log: $('#writeLog'),
  led: $('#led'), pill: $('#savePill'), pillText: $('#saveText'), counter: $('#counter'), toasts: $('#toasts'),
  rawCode: $('#rawCode'), rawPath: $('#rawPath'), rawBytes: $('#rawBytes'),
  del: $('#btnDelete'), delNo: $('[data-no]', els.del), delYes: $('[data=yes]', els.del) || $('.delbtn__btns b:nth-child(1)', els.del),
};
let lastDeleted = null;
let stream = null;

/* ───────────────────────── api ───────────────────────── */
async function api(method, url, body, opts = {}) {
  const t0 = performance.now();
  let res;
  try {
    res = await fetch(url, {
      method,
      keepalive: Boolean(opts.keepalive),
      headers: body ? { 'Content-Type': 'application/json' } : undefined,
      body: body ? JSON.stringify(body) : undefined,
    });
  } catch (err) {
    logOp(method, 'ERR');
    throw err;
  }
  const ms = Math.round(performance.now() - t0);
  logOp(method, res.ok ? res.status : `ERR ${res.status}`);
  if (!res.ok) throw Object.assign(new Error(`${res.status}`), { status: res.status });
  return res.status === 204 ? null : res.json();
}

function logOp(method, status) {
  const li = document.createElement('li');
  const ok = /^(2\d\d|ERR)/.test(String(status)) && String(status) !== 'ERR';
  li.innerHTML = `<b>${method}</b><span class="${ok ? 'ok' : 'bad'}">${esc(String(status))}</span><span>${clock(Date.now())}</span>`;
  els.log.prepend(li);
  while (els.log.children.length > 3) els.log.lastElementChild.remove();
  els.led.classList.add('on');
  setTimeout(() => els.led.classList.remove('on'), 260);
}

/* ───────────────────────── toasts ───────────────────────── */
function toast(text, kind = '', action) {
  const el = document.createElement('div');
  el.className = `toast ${kind}`;
  el.innerHTML = `<span>${esc(text)}</span>`;
  if (action) {
    const b = document.createElement('button');
    b.textContent = action.label;
    b.onclick = () => { action.fn(); dismiss(); };
    el.append(b);
  }
  els.toasts.append(el);
  const dismiss = () => { el.classList.add('out'); setTimeout(() => el.remove(), 240); };
  setTimeout(dismiss, action ? 7000 : 3200);
}

/* ───────────────────────── sidebar ───────────────────────── */
function filtered() {
  const q = state.query.trim().toLowerCase();
  if (!q) return state.sessions;
  return state.sessions.filter((s) => s.title.toLowerCase().includes(q) || s.preview.toLowerCase().includes(q) || s.excerpt.includes(q));
}

function renderList() {
  const items = filtered();
  const focused = document.activeElement === els.search;
  els.list.innerHTML = '';
  if (!items.length) {
    els.list.innerHTML = `<p style="padding:18px 8px;font-size:12px;color:#77808F;font-family:var(--mono)">${state.query ? 'no match' : 'the archive is empty'}</p>`;
  }
  items.forEach((s, i) => {
    const row = document.createElement('div');
    row.className = 'ses' + (s.id === state.current?.id ? ' is-active' : '');
    row.dataset.id = s.id;
    row.setAttribute('role', 'listitem');
    row.tabIndex = 0;
    row.style.animationDelay = `${Math.min(i * 22, 260)}ms`;
    row.innerHTML = `
      <span class="ses__bar"></span>
      <span class="ses__top">
        <span class="ses__title">${s.pinned ? '<span class="ses__pin">◆ </span>' : ''}${esc(s.title)}</span>
        <time datetime="${s.updatedAt}">${rel(s.updatedAt)}</time>
      </span>
      <span class="ses__prev">${esc(s.preview)}</span>
      <span class="ses__meta">${s.messageCount} msg<i class="dot"></i>${bytesLabel(s.bytes)}</span>
      <span class="ses__acts">
        <button class="pin" title="${s.pinned ? 'Unpin' : 'Pin to top'}" data-act="pin">${ICON.pin}</button>
        <button class="del" title="Delete session" data-act="del">${ICON.trash}</button>
      </span>`;
    row.addEventListener('click', (e) => {
      const act = e.target.closest('[data-act]')?.dataset.act;
      if (act === 'pin') return togglePin(s.id);
      if (act === 'del') return row.classList.contains('confirming') ? deleteSession(s.id) : askDelete(row, s.id);
      openSession(s.id);
    });
    row.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openSession(s.id); }
      if (e.key === 'Delete') askDelete(row, s.id);
    });
    els.list.append(row);
  });

  const total = state.sessions.reduce((n, s) => n + s.bytes, 0);
  els.countLabel.textContent = `${state.sessions.length} session${state.sessions.length === 1 ? '' : 's'}`;
  els.diskBytes.textContent = bytesLabel(total);
  if (focused) els.search.focus();
}

function askDelete(row, id) {
  document.querySelectorAll('.ses.confirming').forEach((n) => n.classList.remove('confirming'));
  row.classList.add('confirming');
  const rowTitle = $('.ses__title', row);
  rowTitle.dataset.was = rowTitle.innerHTML;
  rowTitle.innerHTML = 'Delete this session?';
  setTimeout(() => cancelAsk(row, id), 5000);
}
function cancelAsk(row, id) {
  if (!row.classList.contains('confirming')) return;
  row.classList.remove('confirming');
  const t = $('.ses__title', row);
  if (t?.dataset.was) t.innerHTML = t.dataset.was;
}

/* ───────────────────────── session ops ───────────────────────── */
async function loadSessions() {
  const { sessions, dataDir } = await api('GET', '/api/sessions');
  state.sessions = sessions;
  els.diskDir.textContent = dataDir.replace(/^.*(?=\/data\/)/, '…/');
  renderList();
  return sessions;
}

async function newSession() {
  const { session } = await api('POST', '/api/sessions', { title: 'Untitled session', messages: [] });
  state.sessions.unshift({ ...session, bytes: 0, preview: 'No messages yet', excerpt: '' });
  await loadSessions().catch(() => {});
  state.current = session;
  els.search.value = ''; state.query = '';
  renderAll(); els.input.focus();
  toast('New session written to disk');
}

async function openSession(id) {
  finishStream();
  const { session } = await api('GET', `/api/sessions/${id}`);
  state.current = session;
  localStorage.setItem('archivist.last', id);
  renderAll();
  if (window.innerWidth <= 820) els.app.removeAttribute('data-rail');
}

async function togglePin(id) {
  const s = state.sessions.find((x) => x.id === id);
  const { session } = await api('PATCH', `/api/sessions/${id}`, { pinned: !s.pinned });
  if (state.current?.id === id) state.current.pinned = session.pinned;
  await loadSessions();
}

async function deleteSession(id) {
  const summary = state.sessions.find((s) => s.id === id);
  let record = null;
  try { record = (await api('GET', `/api/sessions/${id}`)).session; } catch {}
  await api('DELETE', `/api/sessions/${id}`);
  lastDeleted = record;
  if (state.current?.id === id) {
    state.current = null;
    const rest = state.sessions.filter((s) => s.id !== id);
    if (rest.length) { await loadSessions(); await openSession(rest[0].id); }
    else { await loadSessions(); renderAll(); }
  } else await loadSessions();

  toast('Session deleted', 'bad', record ? {
    label: 'Undo',
    fn: async () => {
      await api('POST', '/api/sessions', { id: record.id, title: record.title, pinned: record.pinned, createdAt: record.createdAt, messages: record.messages });
      await loadSessions(); openSession(record.id);
      toast('Restored from the recycle window');
    },
  } : null);
  if (summary && !record) toast('Session deleted', 'bad');
}

/* ───────────────────────── persistence ───────────────────────── */
function setSave(state_, text) {
  els.pill.dataset.state = state_;
  els.pillText.textContent = text;
}
function scheduleSave(delay = 700) {
  if (!state.current) return;
  setSave('saving', 'unsaved changes');
  clearTimeout(state.saveTimer);
  state.saveTimer = setTimeout(commitSave, delay);
}
async function commitSave(keepalive = false) {
  if (!state.current) return;
  clearTimeout(state.saveTimer);
  setSave('saving', 'saving…');
  const payload = {
    title: state.current.title,
    pinned: state.current.pinned,
    messages: state.current.messages.map(({ streaming, ...m }) => m),
  };
  try {
    const { session, summary } = await api('PUT', `/api/sessions/${state.current.id}`, payload, { keepalive });
    state.current = session;
    const i = state.sessions.findIndex((s) => s.id === summary.id);
    if (i > -1) state.sessions[i] = summary; else state.sessions.unshift(summary);
    state.sessions.sort((a, b) => (b.pinned - a.pinned) || (b.updatedAt > a.updatedAt ? 1 : -1));
    setSave('saved', `saved · ${clock(session.updatedAt)}`);
    renderList(); renderHead(); renderRaw();
  } catch (e) {
    setSave('error', 'save failed');
    if (!keepalive) toast('Could not reach the server — nothing written', 'bad');
  }
}
addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden' && state.current) commitSave(true); });
addEventListener('pagehide', () => { if (state.current) commitSave(true); });

/* ───────────────────────── rendering ───────────────────────── */
function paragraphs(text) {
  return text.split(/\n{2,}/).map((p) => `<p>${esc(p).replace(/\n/g, '<br>')}</p>`).join('');
}
function messageNode(m) {
  const node = document.createElement('article');
  node.className = `msg msg--${m.role}`;
  node.dataset.id = m.id;
  node.innerHTML = `
    <div class="msg__mark">${m.role === 'user' ? 'Y' : 'A'}</div>
    <div class="msg__body">
      <div class="msg__meta"><span>${m.role === 'user' ? 'You' : 'Archivist echo'}</span><time>${clock(m.ts)}</time></div>
      <div class="msg__bubble">${m.streaming ? '<span class="typing"><i></i><i></i><i></i></span>' : paragraphs(m.content)}
        ${m.role === 'assistant' ? `<button class="msg__copy">copy</button>` : ''}
      </div>
    </div>`;
  const c = $('.msg__copy', node);
  if (c) c.onclick = () => { navigator.clipboard.writeText(m.content); c.textContent = 'copied'; setTimeout(() => (c.textContent = 'copy'), 1200); };
  return node;
}
function setBubble(node, text) { $('.msg__bubble', node).innerHTML = `${paragraphs(text)}<button class="msg__copy">copy</button>`; }

function renderThread() {
  const s = state.current;
  els.thread.innerHTML = '';
  if (!s) return renderEmpty('Nothing open', 'Pick a session from the archive, or start a new one — every message you send becomes a line in a JSON file.');
  if (!s.messages.length) return renderEmpty('An empty file, for now', 'Type below. The moment you send, this record stops being empty and starts being history.');
  for (const m of s.messages) els.thread.append(messageNode(m));
  scrollDown(true);
}
function renderEmpty(h, p) {
  els.thread.innerHTML = `
    <div class="empty">
      <div class="stack"><i></i><i></i><i></i></div>
      <h3>${esc(h)}</h3>
      <p>${esc(p)}</p>
      <div class="keys">
        <span>${cmd}K &nbsp;filter archive</span><span>⌥${cmd}N &nbsp;new session</span>
        <span>${cmd}J &nbsp;raw JSON</span><span>${cmd}E &nbsp;export</span>
      </div>
    </div>`;
}
function renderHead() {
  const s = state.current;
  if (!s) { els.title.textContent = ''; els.sid.textContent = '—'; els.headState.textContent = 'no session'; return; }
  if (document.activeElement !== els.title) els.title.textContent = s.title;
  const me = state.sessions.find((x) => x.id === s.id);
  els.sid.textContent = s.id;
  els.headState.textContent = s.pinned ? 'pinned' : 'on disk';
  els.created.textContent = full(s.createdAt);
  els.updated.textContent = `${rel(s.updatedAt)} ago`;
  els.path.textContent = `data/sessions/${s.id}.json`;
  els.mcount.textContent = String(s.messages.length).padStart(2, '0');
  els.fsize.textContent = me ? KB(me.bytes) : '0';
  renderRaw();
}
function highlightJSON(j) {
  return esc(j).replace(
    /("(?:\\u[\da-fA-F]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(?:true|false)\b|\bnull\b|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)/g,
    (m) => {
      let cls = 'num';
      if (/^"/.test(m)) cls = /:\s*$/.test(m) ? 'key' : 'str';
      else if (/true|false/.test(m)) cls = 'bool';
      else if (/null/.test(m)) cls = 'null';
      return `<span class="j-${cls}">${m}</span>`;
    });
}
function renderRaw() {
  if (!state.rawOpen || !state.current) return;
  const s = state.current;
  const json = JSON.stringify(s, null, 2);
  els.rawCode.innerHTML = highlightJSON(json);
  els.rawPath.textContent = `${s.id}.json`;
  els.rawBytes.textContent = bytesLabel(new Blob([json]).size);
}
function renderAll() { renderList(); renderThread(); renderHead(); }

/* ───────────────────────── composer + echo ───────────────────────── */
function autosize() { const t = els.input; t.style.height = 'auto'; t.style.height = `${Math.min(t.scrollHeight, 180)}px`; }
function scrollDown(force) {
  const w = els.threadwrap;
  const near = w.scrollHeight - w.scrollTop - w.clientHeight < 140;
  if (force || near) w.scrollTo({ top: w.scrollHeight, behavior: 'smooth' });
}
function autoTitle() {
  const s = state.current; if (!s) return;
  if (s.title && s.title !== 'Untitled session') return;
  const first = s.messages.find((m) => m.role === 'user')?.content || '';
  if (!first) return;
  s.title = (first.replace(/\s+/g, ' ').trim() + '…').slice(0, 58);
  els.title.textContent = s.title;
}

function finishStream() {
  if (!stream) return;
  clearInterval(stream.timer);
  stream.msg.content = stream.text;
  stream.msg.streaming = false;
  if (stream.node.isConnected) setBubble(stream.node, stream.msg.content);
  stream = null;
  renderRaw();
}

const REPLIES = [
  (t, s) => `Noted — and already filed. That made ${s.messages.length} messages in ${s.id}.json.`,
  (t, s) => `Written to disk before you finished reading it. Reload whenever you like; this transcript is a file, not a memory.`,
  (t, s) => `You said: “${t.slice(0, 72)}${t.length > 72 ? '…' : ''}”. Recorded under ${s.title.toLowerCase()} at ${clock(Date.now())}.`,
  (t, s) => `That is the ${s.messages.length}th entry in this record. Open the raw drawer on the right to see the exact bytes.`,
  (t, s) => `Persisted. Nothing here lives only in this tab — switch sessions and it waits for you on disk.`,
];

/* ⤷ Swap `echoReply` for a real model call: it just needs to return a string (sync or Promise). */
async function echoReply(text, session) {
  const i = session.messages.length % REPLIES.length;
  return REPLIES[i](text, session);
}

async function send() {
  const text = els.input.value.trim();
  if (!text) return;
  finishStream();
  if (!state.current) await newSession();

  const msg = { id: uid(), role: 'user', content: text, ts: Date.now() };
  state.current.messages.push(msg);
  els.input.value = ''; autosize(); els.counter.textContent = '0 chars';
  els.thread.querySelector('.empty')?.remove();
  els.thread.append(messageNode(msg));
  scrollDown(true);
  autoTitle();
  scheduleSave();

  const pending = { id: uid(), role: 'assistant', content: '', ts: Date.now(), streaming: true };
  state.current.messages.push(pending);
  const node = messageNode(pending);
  els.thread.append(node); scrollDown(true);
  const reply = await echoReply(text, state.current);

  pending.content = reply; pending.streaming = false;
  setBubble(node, reply);
  stream = { msg: pending, node, text: reply, timer: null };
  finishStream();
  renderHead();
  scrollDown();
  scheduleSave(200);
}

/* ───────────────────────── events ───────────────────────── */
els.composer.addEventListener('submit', (e) => { e.preventDefault(); send(); });
els.input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); }
});
els.input.addEventListener('input', () => {
  autosize();
  els.counter.textContent = `${els.input.value.length} chars`;
});

els.newChat.addEventListener('click', () => {
  if (state.current && !state.current.messages.length) { toast('Already on a blank session'); els.input.focus(); return; }
  newSession();
});
els.search.addEventListener('input', () => { state.query = els.search.value; renderList(); });
els.search.addEventListener('keydown', (e) => { if (e.key === 'Escape') { els.search.value = ''; state.query = ''; renderList(); els.search.blur(); } });

/* title editing */
els.title.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); els.title.blur(); }
  if (e.key === 'Escape') { els.title.textContent = state.current?.title ?? ''; els.title.blur(); }
});
els.title.addEventListener('paste', (e) => {
  e.preventDefault();
  document.execCommand('insertText', false, e.clipboardData.getData('text/plain').replace(/\s+/g, ' '));
});
els.title.addEventListener('blur', () => {
  const s = state.current; if (!s) return;
  const next = els.title.textContent.replace(/\s+/g, ' ').trim() || 'Untitled session';
  if (next === s.title) { els.title.textContent = next; return; }
