  scheduleSave(150);
});

/* delete flow */
els.del.addEventListener('click', (e) => {
  if (!state.current) return;
  if (!els.del.classList.contains('confirming')) {
    els.del.classList.add('confirming');
    clearTimeout(state.confirmTimer);
    state.confirmTimer = setTimeout(() => els.del.classList.remove('confirming'), 5000);
