});

/* export + raw drawer */
$('#btnExport').addEventListener('click', () => {
  if (!state.current) return;
  const blob = new Blob([JSON.stringify(state.current, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${state.current.id}.json`;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  toast('Downloaded JSON copy');
});
function toggleRaw(force) {
  state.rawOpen = force ?? !state.rawOpen;
  els.app.dataset.raw = state.rawOpen ? 'open' : 'closed';
  $('#btnRaw').classList.toggle('is-on', state.rawOpen);
  localStorage.setItem('archivist.raw', state.rawOpen ? '1' : '0');
  renderRaw();
}
$('#btnRaw').addEventListener('click', () => toggleRaw());
$('#btnRawClose').addEventListener('click', () => toggleRaw(false));
$('#btnRail').addEventListener('click', () => {
  els.app.toggleAttribute('data-rail-open');
  els.app.setAttribute('data-rail', els.app.hasAttribute('data-rail-open') ? 'open' : 'closed');
});

/* shortcuts */
addEventListener('keydown', (e) => {
  const mod = isMac ? e.metaKey : e.ctrlKey;
  if (mod && e.key.toLowerCase() === 'k') { e.preventDefault(); els.search.focus(); els.search.select(); }
  if (mod && e.altKey && e.key.toLowerCase() === 'n') { e.preventDefault(); newSession(); }
  if (mod && !e.shiftKey && e.key.toLowerCase() === 'e') { e.preventDefault(); $('#btnExport').click(); }
  if (mod && e.key.toLowerCase() === 'j') { e.preventDefault(); toggleRaw(); }
  if (e.key === 'Escape') { els.del.classList.remove('confirming'); document.querySelectorAll('.ses.confirming').forEach((n) => cancelAsk(n, n.dataset.id)); }
});

/* live timestamps */
setInterval(() => {
  document.querySelectorAll('.ses time').forEach((t) => { t.textContent = rel(t.dateTime); });
  if (state.current) els.updated.textContent = `${rel(state.current.updatedAt)} ago`;
}, 30000);

/* ───────────────────────── boot ───────────────────────── */
(async function boot() {
  autosize();
  if (localStorage.getItem('archivist.raw') === '1') toggleRaw(true);
  setSave('idle', 'idle');
  try {
    const sessions = await loadSessions();
    const last = localStorage.getItem('archivist.last');
    const pick = sessions.find((s) => s.id === last) || sessions[0];
    if (pick) await openSession(pick.id);
    else { await newSession(); }
    setSave('saved', 'in sync with disk');
  } catch (err) {
    renderEmpty('Server unreachable', 'Start it with `npm start`, then reload. Archivist only speaks to its own JSON store.');
    setSave('error', 'offline');
    toast('Could not reach /api/sessions', 'bad');
  }
  els.input.focus();
})();
