/* ─── tiny api ─── */
async function api(method, url, body, opts = {}) {
  const t0 = performance.now(); let res;
  try {
    res = await fetch(url, { method, keepalive:!!opts.keepalive,
      headers: body ? { 'Content-Type':'application/json' } : undefined, body: body ? JSON.stringify(body) : undefined });
  } catch (e) { logOp(method,'ERR'); throw e; }
  logOp(method, res.ok ? res.status : `ERR ${res.status}`);
  if (!res.ok) throw Object.assign(new Error(`${res.status}`), { status:res.status });
  return res.status === 204 ? null : res.json();
}
function logOp(method,status){ const li=document.createElement('li'); const ok=/^2\d\d/.test(String(status));
  li.innerHTML=`<b>${method}</b><span class="${ok?'ok':'bad'}">${esc(String(status))}</span><span>${clock(Date.now())}</span>`;
  els.log.prepend(li); while(els.log.children.length>3) els.log.lastElementChild.remove();
  els.led.classList.add('on'); setTimeout(()=>els.led.classList.remove('on'),260); }
function toast(text,kind='',action){ const el=document.createElement('div'); el.className=`toast ${kind}`;
  el.innerHTML=`<span>${esc(text)}</span>`; if(action){ const b=document.createElement('button'); b.textContent=action.label;
  b.onclick=()=>{action.fn();dismiss();}; el.append(b);} els.toasts.append(el);
  const dismiss=()=>{el.classList.add('out'); setTimeout(()=>el.remove(),240);}; setTimeout(dismiss, action?7000:3200); }

/* ════════════════════════ THE REQUEST BUILDER ════════════════════════
   One place decides the OpenAI-vs-extra_body split, so the live preview
   is guaranteed identical to what /api/chat forwards to llama.cpp.       */
function buildRequest(conv, stream = true) {
  const s = state.settings;
  const messages = (s.system && s.system.trim())
    ? [{ role:'system', content:s.system }, ...conv]
    : [...conv];
  // named kwargs that ARE in the OpenAI schema → top level
  const standard = {
    model: s.model || 'local-model',
    messages, stream,
    temperature: rnd(s.temperature, 2),
    top_p: rnd(s.top_p, 2),
    max_tokens: Math.round(s.max_tokens),
  };
  // llama.cpp samplers that are NOT in the OpenAI schema → extra_body
  const extra_body = {
    top_k: Math.round(s.top_k),
    min_p: rnd(s.min_p, 3),
    repeat_penalty: rnd(s.repeat_penalty, 3),
  };
  // SDK semantics flatten extra_body into the JSON root, which is exactly what
  // llama-server parses. Flip to 'nest' only behind a proxy that re-splats it.
  return s.wireMode === 'nest' ? { ...standard, extra_body } : { ...standard, ...extra_body };
}
const snapshotParams = () => ({
  model: state.settings.model, temperature: state.settings.temperature, top_p: state.settings.top_p,
  top_k: Math.round(state.settings.top_k), min_p: state.settings.min_p,
  repeat_penalty: state.settings.repeat_penalty, max_tokens: Math.round(state.settings.max_tokens),
  via: state.llamaOnline ? 'llama.cpp' : 'echo',
});

