async function loadSessions(){ const {sessions,dataDir}=await api('GET','/api/sessions'); state.sessions=sessions;
  els.diskDir.textContent=dataDir.replace(/^.*(?=\/data\/)/,'…/'); renderList(); return sessions; }
async function newSession(){ const {session}=await api('POST','/api/sessions',{title:'Untitled session',messages:[]});
  state.sessions.unshift({...session,bytes:0,preview:'No messages yet',excerpt:''}); await loadSessions().catch(()=>{});
  state.current=session; els.search.value=''; state.query=''; renderAll(); els.input.focus(); toast('New session written to disk'); }
async function openSession(id){ const {session}=await api('GET',`/api/sessions/${id}`); state.current=session;
  localStorage.setItem('archivist.last',id); renderAll(); if(innerWidth<=820) els.app.removeAttribute('data-rail'); }
async function togglePin(id){ const s=state.sessions.find(x=>x.id===id); await api('PATCH',`/api/sessions/${id}`,{pinned:!s.pinned});
  if(state.current?.id===id)state.current.pinned=!s.pinned; await loadSessions(); }
async function deleteSession(id){ let record=null; try{record=(await api('GET',`/api/sessions/${id}`)).session;}catch{}
  await api('DELETE',`/api/sessions/${id}`);
  if(state.current?.id===id){ state.current=null; const rest=state.sessions.filter(s=>s.id!==id);
    if(rest.length){await loadSessions();await openSession(rest[0].id);} else {await loadSessions();renderAll();} } else await loadSessions();
  toast('Session deleted','bad',record?{label:'Undo',fn:async()=>{ await api('POST','/api/sessions',{id:record.id,title:record.title,pinned:record.pinned,createdAt:record.createdAt,messages:record.messages}); await loadSessions(); openSession(record.id); toast('Restored'); }}:null); }

/* ─── persistence of transcript ─── */
function setSave(s,t){ els.pill.dataset.state=s; els.pillText.textContent=t; }
function scheduleSave(d=700){ if(!state.current)return; setSave('saving','unsaved changes'); clearTimeout(state.saveTimer); state.saveTimer=setTimeout(commitSave,d); }
async function commitSave(keepalive=false){ if(!state.current)return; clearTimeout(state.saveTimer); setSave('saving','saving…');
  const payload={ title:state.current.title, pinned:state.current.pinned,
    messages:state.current.messages.map(({streaming,...m})=>m) };
  try{ const {session,summary}=await api('PUT',`/api/sessions/${state.current.id}`,payload,{keepalive}); state.current=session;
    const i=state.sessions.findIndex(s=>s.id===summary.id); if(i>-1)state.sessions[i]=summary; else state.sessions.unshift(summary);
    state.sessions.sort((a,b)=>(b.pinned-a.pinned)||(b.updatedAt>a.updatedAt?1:-1));
    setSave('saved',`saved · ${clock(session.updatedAt)}`); renderList(); renderHead(); renderRaw();
  }catch{ setSave('error','save failed'); if(!keepalive)toast('Could not reach server — nothing written','bad'); } }
addEventListener('visibilitychange',()=>{ if(document.visibilityState==='hidden'&&state.current)commitSave(true); });
addEventListener('pagehide',()=>{ if(state.current)commitSave(true); });

