const paragraphs=(t)=>t.split(/\n{2,}/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
function fmt2(v){ return (v==null?'':String(v)); }
function provText(p){ if(!p)return''; return p.via==='echo'?`local echo`:`${p.model.split('/').pop()} · t${rnd(p.temperature,2)} · p${rnd(p.top_p,2)} · k${p.top_k}`; }
