function renderThread(){ const s=state.current; els.thread.innerHTML=''; if(!s)return renderEmpty('Nothing open','Pick a session, or start one — every message becomes a line in a JSON file.');
  if(!s.messages.length)return renderEmpty('An empty file, for now','Type below. The moment you send, this record starts being history.');
  for(const m of s.messages) els.thread.append(messageNode(m)); scrollDown(true); }
function renderEmpty(h,p){ els.thread.innerHTML=`<div class="empty"><div class="stack"><i></i><i></i><i></i></div><h3>${esc(h)}</h3><p>${esc(p)}</p>
  <div class="keys"><span>${cmd}K filter</span><span>⌥${cmd}N new</span><span>${cmd}J raw</span><span>${cmd}, settings</span></div></div>`; }
function renderHead(){ const s=state.current; if(!s){els.title.textContent='';els.sid.textContent='—';els.headState.textContent='no session';return;}
