  els.updated.textContent=`${rel(s.updatedAt)} ago`; els.path.textContent=`data/sessions/${s.id}.json`;
  els.mcount.textContent=String(s.messages.length).padStart(2,'0'); els.fsize.textContent=me?KB(me.bytes):'0'; renderRaw(); }
function highlightJSON(j){ return esc(j).replace(/("(?:\\u[\da-fA-F]{4}|\\[^u]|[^\\"])*"(\s*:)?|\b(?:true|false)\b|\bnull\b|-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)/g,(m)=>{
  let c='num'; if(/^"/.test(m))c=/:\s*$/.test(m)?'key':'str'; else if(/true|false/.test(m))c='bool'; else if(/null/.test(m))c='null'; return `<span class="j-${c}">${m}</span>`; }); }
