    wrap.innerHTML=`<div class="slider__top"><label class="slider__label" for="sl-${f.k}">${f.k}${f.openai?'':' <i class="flag">extra_body</i>'}</label>
      <output class="slider__val" id="val-${f.k}"></output></div>
