function queuePreview(){ clearTimeout(state.prevTimer); state.prevTimer=setTimeout(updatePreview,40); }
function currentConv(){ const s=state.current; if(s&&s.messages.length) return s.messages.filter(m=>!m.streaming).map(({role,content})=>({role,content}));
  return [{role:'user',content:'hello there'}]; }
function updatePreview(){ const body=buildRequest(currentConv(),true); const json=JSON.stringify(body,null,2);
  let disp=json;
  if(state.settings.wireMode==='flatten'){ disp=disp.split('\n').map(l=>{ const m=l.match(/^\s*"([a-z_]+)":/); return m&&EXTRA_KEYS.includes(m[1])?l+'  // extra_body':l; }).join('\n'); }
  els.prevCode.innerHTML=highlightJSON(disp).replace(/\/\/ extra_body/g,'<span class="j-com">// extra_body</span>');
