    state.llamaOnline=!!h.ok; state.endpointText=h.url; els.endpoint.textContent=`llama.cpp · ${h.url}`;
    els.connDot.className='conn__dot '+(h.ok?'up':'down'); els.connTxt.textContent=h.ok?'online':'offline — echo fallback';
    els.llamaDot.className='gear__dot '+(h.ok?'up':'down');
