/* ─── real streaming chat (SSE passthrough) ─── */
async function streamChat(body,onDelta){ const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body})});
  if(!res.ok){ let d=''; try{const j=await res.json(); d=j.detail||j.error||'';}catch{} throw new Error(`llama.cpp ${res.status} — ${d}`.slice(0,160)); }
  const ct=res.headers.get('content-type')||'';
  if(ct.includes('event-stream')&&res.body){ const rd=res.body.getReader(),dec=new TextDecoder(); let buf='',full='',i;
    while(true){ const {value,done}=await rd.read(); if(done)break; buf+=dec.decode(value,{stream:true});
      while((i=buf.indexOf('\n'))>=0){ const line=buf.slice(0,i); buf=buf.slice(i+1); const s=line.trim();
        if(!s.startsWith('data:'))continue; const p=s.slice(5).trim(); if(p==='[DONE]')return full;
        try{ const j=JSON.parse(p); const d=j.choices?.[0]?.delta?.content??j.content_hint??''; if(d){full+=d; onDelta(full);} }catch{} } }
    return full;
  } const j=await res.json(); const c=j.choices?.[0]?.message?.content??''; onDelta(c); return c; }

/* ─── local echo fallback ─── */
const REPLIES=[
  (t,s)=>`Noted — and already filed. That made ${s.messages.length} messages.`,
  (t,s)=>`Written to disk before you finished reading it. Reload and this transcript is a file, not a memory.`,
  (t,s)=>`You said: “${t.slice(0,72)}${t.length>72?'…':''}”. Recorded under ${s.title.toLowerCase()}.`,
  (t,s)=>`That's the ${s.messages.length}th entry. Open the raw drawer to see the exact bytes.`,
  (t,s)=>`Persisted. Nothing here lives only in this tab.`,
];
async function echoReply(t,s){ await new Promise(r=>setTimeout(r,180)); return REPLIES[s.messages.length%REPLIES.length](t,s); }

/* ─── send ─── */
function autosize(){ const t=els.input; t.style.height='auto'; t.style.height=`${Math.min(t.scrollHeight,180)}px`; }
function scrollDown(force){ const w=els.threadwrap; const near=w.scrollHeight-w.scrollTop-w.clientHeight<140; if(force||near)w.scrollTo({top:w.scrollHeight,behavior:'smooth'}); }
function autoTitle(){ const s=state.current; if(!s||(s.title&&s.title!=='Untitled session'))return;
  const first=s.messages.find(m=>m.role==='user')?.content||''; if(!first)return; s.title=(first.replace(/\s+/g,' ').trim()+'…').slice(0,58); els.title.textContent=s.title; }
async function send(){ const text=els.input.value.trim(); if(!text)return;
  if(!state.current)await newSession();
  const msg={id:uid(),role:'user',content:text,ts:Date.now()}; state.current.messages.push(msg);
  els.input.value=''; autosize(); els.counter.textContent='0 chars'; els.thread.querySelector('.empty')?.remove();
  els.thread.append(messageNode(msg)); scrollDown(true); autoTitle(); scheduleSave();
  const params=snapshotParams();
  const pending={id:uid(),role:'assistant',content:'',ts:Date.now(),streaming:true};
  state.current.messages.push(pending); const node=messageNode(pending); els.thread.append(node); scrollDown(true);
  let reply='';
  if(state.llamaOnline){
    const body=buildRequest(state.current.messages.filter(m=>!m.streaming).slice(0,-1?undefined:undefined),true);
    // buildRequest already excludes system injection duplication; pass full conv (assistant just pushed w/ empty removed below)
    const conv=state.current.messages.filter(m=>!(m.id===pending.id)).map(({role,content})=>({role,content}));
    const reqBody=buildRequest(conv,true);
    try{ reply=await streamChat(reqBody,(t)=>{ pending.content=t; setBubble(node,t); scrollDown(false); }); }
    catch(err){ reply=await echoReply(text,state.current); setBubble(node,reply); toast(err.message||'llama.cpp error — used local echo','bad'); params.via='echo'; }
  } else { reply=await echoReply(text,state.current); setBubble(node,reply); }
  pending.content=reply; pending.streaming=false; pending.params=params;
  const meta=$('.msg__meta',node); if(meta&&params){ const sp=document.createElement('span'); sp.className='msg__prov'; sp.textContent=provText(params); meta.append(sp); }
  const who=$('.msg__meta span',node); if(who&&params&&params.via!=='echo')who.textContent='Archivist';
  renderHead(); scheduleSave(150); renderRaw();
}

/* ─── events ─── */
els.composer.addEventListener('submit',e=>{e.preventDefault();send();});
els.input.addEventListener('keydown',e=>{ if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();} });
els.input.addEventListener('input',()=>{ autosize(); els.counter.textContent=`${els.input.value.length} chars`; });
els.newChat.addEventListener('click',()=>{ if(state.current&&!state.current.messages.length){toast('Already on a blank session');els.input.focus();return;} newSession(); });
els.search.addEventListener('input',()=>{ state.query=els.search.value; renderList(); });
els.search.addEventListener('keydown',e=>{ if(e.key==='Escape'){els.search.value='';state.query='';renderList();els.search.blur();} });
els.title.addEventListener('keydown',e=>{ if(e.key==='Enter'){e.preventDefault();els.title.blur();} if(e.key==='Escape'){els.title.textContent=state.current?.title??'';els.title.blur();} });
els.title.addEventListener('paste',e=>{ e.preventDefault(); document.execCommand('insertText',false,e.clipboardData.getData('text/plain').replace(/\s+/g,' ')); });
els.title.addEventListener('blur',()=>{ const s=state.current; if(!s)return; const n=els.title.textContent.replace(/\s+/g,' ').trim()||'Untitled session'; if(n===s.title){els.title.textContent=n;return;} s.title=n; scheduleSave(150); });
els.delYes.onclick=e=>{ e.stopPropagation(); els.del.classList.remove('confirming'); if(state.current)deleteSession(state.current.id); };
els.delNo.onclick=e=>{ e.stopPropagation(); els.del.classList.remove('confirming'); };
els.del.addEventListener('click',e=>{ if(e.target.closest('b'))return; if(!state.current)return;
  els.del.classList.toggle('confirming'); clearTimeout(state.confirmTimer); state.confirmTimer=setTimeout(()=>els.del.classList.remove('confirming'),5000); });
$('#btnExport').addEventListener('click',()=>{ if(!state.current)return; const blob=new Blob([JSON.stringify(state.current,null,2)],{type:'application/json'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=`${state.current.id}.json`; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),1000); toast('Downloaded JSON copy'); });
function toggleRaw(force){ state.rawOpen=force??!state.rawOpen; els.app.dataset.raw=state.rawOpen?'open':'closed';
  $('#btnRaw').classList.toggle('is-on',state.rawOpen); localStorage.setItem('archivist.raw',state.rawOpen?'1':'0'); renderRaw(); }
$('#btnRaw').addEventListener('click',()=>toggleRaw());
$('#btnRawClose').addEventListener('click',()=>toggleRaw(false));
$('#btnGear').addEventListener('click',()=>openSettings());
$('#btnRail').addEventListener('click',()=>{ const open=els.app.toggleAttribute('data-rail-open'); els.app.setAttribute('data-rail',open?'open':'closed'); });
addEventListener('keydown',e=>{ const mod=isMac?e.metaKey:e.ctrlKey;
  if(mod&&e.key.toLowerCase()==='k'){e.preventDefault();els.search.focus();els.search.select();}
  if(mod&&e.altKey&&e.key.toLowerCase()==='n'){e.preventDefault();newSession();}
  if(mod&&!e.shiftKey&&e.key.toLowerCase()==='e'){e.preventDefault();$('#btnExport').click();}
  if(mod&&e.key.toLowerCase()==='j'){e.preventDefault();toggleRaw();}
  if(mod&&e.key===','){e.preventDefault();openSettings();}
  if(e.key==='Escape'&&state.sheetOpen){openSettings(false);} });
setInterval(()=>{ document.querySelectorAll('.ses time').forEach(t=>t.textContent=rel(t.dateTime)); if(state.current)els.updated.textContent=`${rel(state.current.updatedAt)} ago`; },30000);

/* ─── boot ─── */
(async function boot(){ autosize(); if(localStorage.getItem('archivist.raw')==='1')toggleRaw(true); setSave('idle','idle');
  buildSliders();
  try{ const s=await api('GET','/api/settings'); state.settings=s; } catch{ try{state.settings=JSON.parse(localStorage.getItem('archivist.settings'))||state.settings;}catch{} }
  renderSettingsForm();
  await probeLlama(); setInterval(probeLlama,15000);
  try{ const sessions=await loadSessions(); const last=localStorage.getItem('archivist.last');
    const pick=sessions.find(x=>x.id===last)||sessions[0]; if(pick)await openSession(pick.id); else await newSession();
    setSave('saved','in sync with disk'); }
  catch{ renderEmpty('Server unreachable','Start it with `node server.js`, then reload.'); setSave('error','offline'); toast('Could not reach /api/sessions','bad'); }
  els.input.focus();
})();
```

